"""Code-native illustrations and visual story panels for TaxOS."""
from html import escape as e


def portrait(kind):
    hair = '<path d="M77 93Q61 27 115 28Q165 29 148 100L136 67Q107 82 82 62Z" fill="#282a32"/>' if kind == 'client' else '<path d="M76 67Q74 27 113 29Q154 28 148 69L129 53L81 73Z" fill="#282a32"/>'
    glasses = '<g fill="none" stroke="#292832" stroke-width="3"><rect x="83" y="76" width="25" height="17" rx="6"/><rect x="116" y="76" width="25" height="17" rx="6"/><path d="M108 81h8"/></g>' if kind != 'client' else ''
    return f'''<svg viewBox="0 0 220 190" aria-hidden="true"><circle cx="110" cy="94" r="79" fill="currentColor" opacity=".2"/><path d="M46 183q4-65 64-65t64 65" fill="currentColor" stroke="#292832" stroke-width="3"/><path d="M96 111v24q14 15 28 0v-24" fill="#d49b79" stroke="#292832" stroke-width="3"/>{hair}<ellipse cx="111" cy="82" rx="35" ry="43" fill="#e9b58f" stroke="#292832" stroke-width="3"/>{hair}{glasses}<g fill="#292832"><circle cx="97" cy="83" r="2"/><circle cx="127" cy="83" r="2"/></g><path d="M109 87l-3 12h8m-14 9q11 8 22-1" fill="none" stroke="#292832" stroke-width="2" stroke-linecap="round"/><path d="M77 151l13 32m54-32-13 32" stroke="#292832" stroke-width="3" fill="none"/></svg>'''


def personas():
    people=[('cpa','01 / THE PREPARER','The CPA','Find what’s missing. Start the work.','India-based · US tax preparation','Scattered files + manual workpapers','One view of tasks, documents and preparation'),('client','02 / THE CONTRIBUTOR','The client','Show me what you need from me.','US client · document collection','Unclear requests + repeated follow-ups','Relevant questions and a clear upload path'),('lead','03 / THE COORDINATOR','The firm lead','Keep the whole team moving.','Accounting firm · multiple clients','Preparation bottlenecks during tax season','A repeatable workflow across client accounts')]
    return '<p class="visual-caption">ILLUSTRATIVE PERSONAS · ROLE SUMMARIES, NOT INTERVIEW QUOTES</p><div class="persona-board">'+''.join(f'''<article class="persona-card persona-{kind}"><span class="persona-index">{num}</span><div class="persona-portrait">{portrait(kind)}</div><h3>{title}</h3><p class="persona-context">{context}</p><p class="persona-intent">{intent}</p><dl><div><dt>Friction</dt><dd>{pain}</dd></div><div><dt>Design response</dt><dd>{need}</dd></div></dl><a class="persona-explore" href="#decisions" data-persona="{kind}">Follow this perspective →</a></article>''' for kind,num,title,intent,context,pain,need in people)+'</div>'


def workflow():
    scenes = [
        ('Collect', 'First, get the right information.', 'The client is left guessing.', 'Requests arrive in separate messages. Missing files trigger another follow-up.',
         '<div class="wf-message"><span>CPA → CLIENT</span><p>Could you send the remaining documents?</p></div><div class="wf-message wf-reply"><span>CLIENT → CPA</span><p>Which ones do you still need?</p></div><span class="wf-friction">↻ Another follow-up</span>',
         'Give the client a clear next step.', 'Relevant questions and a shared checklist guide document collection.',
         '<div class="wf-window"><div class="wf-window-bar"><span>CLIENT PORTAL</span><span>01 / INTAKE</span></div><h4>Let’s get your documents ready.</h4><div class="wf-question">Tell us about your income <span>→</span></div><div class="wf-check">✓ <span>Documents received</span></div><div class="wf-check wf-pending">○ <span>Remaining documents to upload</span></div></div>', 'Clarity replaces chasing.'),
        ('Organize', 'Then, make sense of the files.', 'Receiving a file is only the start.', 'Source documents and task lists sit apart. The CPA still has to reconcile them.',
         '<div class="wf-file-stack"><span>▤ Client documents</span><span>☷ Separate task list</span><span>▦ Manual reconciliation</span></div><span class="wf-friction">↻ Match files across tools</span>',
         'Connect documents to the checklist.', 'Assisted matching brings received files and preparation requirements together.',
         '<div class="wf-window"><div class="wf-window-bar"><span>DOCUMENT WORKSPACE</span><span>02 / ORGANIZE</span></div><h4>Give every file a place.</h4><div class="wf-match"><span>▤ Uploaded files</span><b>↓</b><span>✧ Assisted matching</span><b>↓</b><span>☷ Linked checklist</span></div></div>', 'A collection becomes usable information.'),
        ('Prepare', 'Now, the preparation can begin.', 'Re-enter. Check. Repeat.', 'Moving document data into Excel adds another manual step before preparation.',
         '<div class="wf-copy-scene"><span>▤ Source document</span><b>↓ copy data by hand</b><div class="wf-spreadsheet" aria-hidden="true">'+ '<i></i>'*12 +'</div><span>Excel workpaper</span></div><span class="wf-friction">↻ Repeated data entry</span>',
         'Bring the starting point to the CPA.', 'Assisted extraction and workpapers support preparation in one workspace.',
         '<div class="wf-window"><div class="wf-window-bar"><span>CPA WORKSPACE</span><span>03 / PREPARE</span></div><h4>Start with organized inputs.</h4><div class="wf-check">▤ <span>Source documents</span></div><div class="wf-check">✧ <span>Assisted extraction</span></div><div class="wf-ready">Workpaper preparation →</div></div>', 'Less switching. A clearer starting point.')
    ]
    controls = ''.join(f'<button type="button" data-flow-step="{i}" aria-pressed="{str(i == 0).lower()}" aria-controls="workflow-stage-{i}"><span>0{i+1}</span>{item[0]}<b aria-hidden="true">→</b></button>' for i,item in enumerate(scenes))
    panels = ''
    for i, (name, heading, before_title, before_copy, before_art, after_title, after_copy, after_art, takeaway) in enumerate(scenes):
        panels += f'''<section class="wf-stage" id="workflow-stage-{i}" data-flow-panel="{i}" aria-labelledby="workflow-title-{i}"><div class="wf-stage-heading"><h3 id="workflow-title-{i}">{heading}</h3><span>0{i+1} / 03</span></div><div class="wf-comparison"><article class="wf-before"><p class="wf-side-label"><span>BEFORE</span> Disconnected tools</p><div class="wf-art">{before_art}</div><h4>{before_title}</h4><p>{before_copy}</p></article><div class="wf-bridge" aria-hidden="true">→</div><article class="wf-after"><p class="wf-side-label"><span>WITH TAXOS</span> One connected workflow</p><div class="wf-art">{after_art}</div><h4>{after_title}</h4><p>{after_copy}</p></article></div><p class="wf-takeaway"><span aria-hidden="true">↳</span>{takeaway}</p></section>'''
    return f'''<div class="workflow-lab"><div class="wf-intro"><span class="scene-tag">FROM FRICTION TO FLOW</span><p>Watch the handoff become a flow.</p></div><div class="flow-explorer wf-controls" hidden><div role="group" aria-label="Explore workflow stages">{controls}</div><div class="wf-playback"><span data-flow-play-label>Animated walkthrough · 8 seconds per scene</span><button type="button" data-flow-play aria-label="Pause animated walkthrough">Pause ⏸</button></div><div class="wf-timer" aria-hidden="true"><span data-flow-timer></span></div><p class="wf-sr-only" data-flow-copy role="status">Step 1 of 3: Collect.</p></div>{panels}<p class="wf-footnote">Simplified workflow illustrations · not live product screens</p></div>'''


def decisions():
    cards=[('01','Two doors. One workflow.','Clients provide information. CPAs prepare the work. Each gets a focused space.','<div class="mini-split"><span>CLIENT<br><b>Questions<br>Uploads</b></span><i>↔</i><span>CPA<br><b>Tasks<br>Workpapers</b></span></div>'),('02','Ask only what matters.','Adaptive intake connects client answers to the documents they need to supply.','<div class="mini-branch"><span>Client response</span><i>↙ &nbsp; ↘</i><div><span>Relevant<br>question</span><span>Required<br>document</span></div></div>'),('03','Turn files into a starting point.','Assisted matching and extraction bring source information into preparation.','<div class="mini-pipeline"><span>Files<br>▤ ▤</span><i>→</i><span>AI assist<br>✧</span><i>→</i><span>Workpaper<br>☷</span></div>'),('04','Make it work before building it.','A functional prototype with mock data let CPAs try the flow before production.','<div class="mini-prototype"><span>Design</span><i>→</i><span>Working<br>prototype</span><i>→</i><span>CPA<br>feedback</span></div>')]
    return '<p class="visual-caption">CONCEPT DIAGRAMS · SIMPLIFIED TO EXPLAIN THE DESIGN</p><p class="persona-reading" data-persona-reading hidden role="status"></p><div class="visual-decisions">'+''.join(f'<article data-decision="{n}"><div class="decision-sketch" aria-hidden="true">{art}</div><span class="scene-tag">DESIGN MOVE / {n}</span><h3>{title}</h3><p>{copy}</p></article>' for n,title,copy,art in cards)+'</div>'


def storyboard():
    return '''<div class="story-overview" aria-label="The story in three steps"><div><span>01 / THE TENSION</span><strong>Chasing files.</strong><p>Preparation stalls before it starts.</p></div><b aria-hidden="true">→</b><div><span>02 / MY DESIGN FOCUS</span><strong>Connect the handoff.</strong><p>Client portal + CPA workspace.</p></div><b aria-hidden="true">→</b><div><span>03 / THE DIRECTION</span><strong>Ready to prepare.</strong><p>Organized inputs, less tool switching.</p></div></div>'''


def guide():
    return '''<div class="story-start"><div><p class="handwritten">Let me walk you through it ↘</p><p>Follow the problem, the people and the design. Explore at your own pace.</p></div><a class="button button-yellow" href="#problem" data-guide-start>Start the story →</a></div><nav class="story-guide" aria-label="Guided case study" hidden><div class="guide-position"><span data-guide-count>01 / 06</span><strong data-guide-title>The problem</strong><progress data-guide-progress max="6" value="1" aria-label="Current story chapter">1 of 6</progress></div><a href="#problem" data-guide-prev aria-label="Previous chapter">←</a><a href="#research" data-guide-next>Meet the people →</a><button type="button" data-guide-close aria-label="Close guided walkthrough">×</button></nav>'''
